DECLARE @table NVARCHAR(128) = @user_input;
DECLARE @sql NVARCHAR(MAX) = N'SELECT * FROM ' + @table;
EXEC sp_executesql @sql;

-- The attacker passes: 'users; DROP TABLE orders; --'
-- Resulting SQL: SELECT * FROM users; DROP TABLE orders; --

CREATE OR ALTER PROC usp_safe_query
    @schema SYSNAME,
    @table  SYSNAME
AS
BEGIN
    DECLARE @sql NVARCHAR(MAX);
    SET @sql = N'SELECT * FROM ' + QUOTENAME(@schema) + '.' + QUOTENAME(@table);
    EXEC sp_executesql @sql;
END;

CREATE OR ALTER PROC usp_search_products
    @categoryId  INT = NULL,
    @minPrice    DECIMAL(10,2) = NULL,
    @brandName   NVARCHAR(100) = NULL
AS
BEGIN
    DECLARE @sql  NVARCHAR(MAX) = N'SELECT product_name, list_price FROM production.products WHERE 1 = 1';
    DECLARE @params NVARCHAR(500) = N'';

    IF @categoryId IS NOT NULL
    BEGIN
        SET @sql += N' AND category_id = @categoryId';
        SET @params += N'@categoryId INT, ';
    END
    IF @minPrice IS NOT NULL
    BEGIN
        SET @sql += N' AND list_price >= @minPrice';
        SET @params += N'@minPrice DECIMAL(10,2), ';
    END

    -- remove trailing comma+space from @params
    SET @params = LEFT(@params, LEN(@params) - 2);

    EXEC sp_executesql @sql, @params,
        @categoryId = @categoryId,
        @minPrice = @minPrice;
END;
